const ids=[];await figma.loadFontAsync({family:'Noto Sans SC',style:'Regular'});await figma.loadFontAsync({family:'Noto Sans SC',style:'Medium'});
const fill=h=>[{type:'SOLID',color:{r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255}}];
function box(parent,name,w,h,bg){const n=figma.createAutoLayout('VERTICAL');parent.appendChild(n);n.name=name;n.resize(w,h);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';n.fills=bg?fill(bg):[];ids.push(n.id);return n;}
function textNode(parent,name,value,size=16,width=342,color='171717'){const n=figma.createText();parent.appendChild(n);n.name=name;n.fontName={family:'Noto Sans SC',style:size>=24?'Medium':'Regular'};n.fontSize=size;n.lineHeight={unit:'PIXELS',value:size>=24?42:24};n.characters=value;n.resize(width,24);n.textAutoResize='HEIGHT';n.fills=fill(color);ids.push(n.id);return n;}
async function currentFonts(n){for(const t of n.findAllWithCriteria({types:['TEXT']}))for(const s of t.getStyledTextSegments(['fontName']))await figma.loadFontAsync(s.fontName);}
async function instance(parent,mainId,name,label,prop,w=342,h=52){const main=await figma.getNodeByIdAsync(mainId);await currentFonts(main);const n=main.createInstance();parent.appendChild(n);n.name=name;for(const t of n.findAllWithCriteria({types:['TEXT']})){t.fontName={family:'Noto Sans SC',style:'Regular'};}n.setProperties({[prop]:label});n.resize(w,h);ids.push(n.id,...n.findAll(()=>true).map(n=>n.id));return n;}

